import numpy as np
import pandas as pd

def baseline_mses():
    x = pd.read_csv('spread-daily.csv')['spread_bp'].to_numpy(float)
    train, prev, nxt = x[:350], x[349:-1], x[350:]
    slope, icpt = np.polyfit(train[:-1], train[1:], 1)
    return {'persistence': float(np.mean((nxt - prev) ** 2)),
            'mean': float(np.mean((nxt - train.mean()) ** 2)),
            'ar1': float(np.mean((nxt - (icpt + slope * prev)) ** 2))}
